//! The corpus of open-source Java projects used in tests.
//!
//! Projects are listed in `projects.toml`, pinned to a commit. For each project, a lock file in
//! `lock/` records its modules and source sets: source roots, Java release, and classpath. Lock files
//! are generated by running the project's own build once (`corpus lock`), so fetching never runs a
//! build. Fetched files go to `target/corpus`, or to `FERRION_CORPUS_DIR` if it is set.
//!
//! The `corpus` binary fetches and locks projects; other test tools use this library to find them.

pub mod fetch;
mod gradle;
pub mod lock;
mod maven;
pub mod project;

use std::path::PathBuf;

use anyhow::{Result, bail};

use crate::project::Project;

/// Where the tool's inputs and outputs live.
pub struct Dirs {
    /// `tools/corpus`, which holds `projects.toml` and `lock/`.
    pub tool: PathBuf,
    /// Where projects and jars are fetched to.
    pub corpus: PathBuf,
}

impl Dirs {
    pub fn new() -> Result<Self> {
        let tool = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
        let corpus = match std::env::var_os("FERRION_CORPUS_DIR") {
            Some(dir) => PathBuf::from(dir),
            None => tool.join("../../target/corpus"),
        };
        // Builds report canonical paths, so the corpus path is made canonical to compare with them.
        std::fs::create_dir_all(&corpus)?;
        let corpus = corpus.canonicalize()?;
        Ok(Dirs { tool, corpus })
    }

    pub fn projects_file(&self) -> PathBuf {
        self.tool.join("projects.toml")
    }

    pub fn checkout(&self, project: &Project) -> PathBuf {
        self.corpus.join("projects").join(&project.name)
    }

    pub fn jars(&self) -> PathBuf {
        self.corpus.join("jars")
    }

    pub fn lock_file(&self, project: &Project) -> PathBuf {
        self.tool
            .join("lock")
            .join(format!("{}.json", project.name))
    }
}

/// The projects named in `names`, in that order, or every project if `names` is empty.
pub fn select<'a>(projects: &'a [Project], names: &[String]) -> Result<Vec<&'a Project>> {
    if names.is_empty() {
        return Ok(projects.iter().collect());
    }
    names
        .iter()
        .map(
            |name| match projects.iter().find(|project| &project.name == name) {
                Some(project) => Ok(project),
                None => bail!("unknown project `{name}`"),
            },
        )
        .collect()
}
